root.command:

IF OBJECT_ID(N'dbo.CourierServicesTbl', N'U') IS NOT NULL
   AND COL_LENGTH(N'dbo.CourierServicesTbl', N'TrackingUrlParam') IS NULL
    ALTER TABLE dbo.CourierServicesTbl ADD TrackingUrlParam NVARCHAR(100) NULL;


IF OBJECT_ID(N'dbo.OrderWaybillTbl', N'U') IS NOT NULL
   AND COL_LENGTH(N'dbo.OrderWaybillTbl', N'CourierServiceID') IS NULL
    ALTER TABLE dbo.OrderWaybillTbl ADD CourierServiceID INT NULL;


SELECT CourierServiceID, ServiceCode, ServiceName, TrackingUrl, TrackingUrlParam, IsDefault, IsEnabled, SortOrder
FROM dbo.CourierServicesTbl
ORDER BY SortOrder, ServiceName;
